N=len(target)
pair=[-1]*N; stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def hairpin_loops():
    loops=[]
    for i in range(N):
        j=pair[i]
        if j>i and all(pair[k]==-1 for k in range(i+1,j)):
            loops.append((i,j))
    return loops
loops=hairpin_loops()

