    seq=['A']*N
    for i in range(N):
        if pair[i]>i:
            seq[i]='G'; seq[pair[i]]='C'
        elif pair[i]==-1:
            seq[i]='A'
    for (i,j) in loops:
        L=j-i-1
        if L==4:
            for k,c in zip(range(i+1,j),"GAAA"): seq[k]=c
        elif L==3:
            for k,c in zip(range(i+1,j),"GAA"): seq[k]=c
    return ''.join(seq)

def dist(s):
    st,_=RNA.fold_compound(s).mfe()
    return RNA.bp_distance(st,target)

base=build()
print("base dist", dist(base))

# Hill climb with random mutations, accept if dist drops, with sideways moves
random.seed(1)
cur=base; cur_d=dist(cur)
best, best_d=cur, cur_d
import time
deadline=time.time()+120
while time.time()<deadline and best_d>0:
    c=list(cur)
    for _ in range(random.choice([1,1,2,3])):
        i=random.randrange(N)
        c[i]=random.choice('ACGU')
    c=''.join(c)
    d=dist(c)
    if d<cur_d or (d==cur_d and random.random()<0.5):
        cur,cur_d=c,d
        if d<best_d: best,best_d=c,d
print("best dist", best_d)
print(best)
